<script>
(() => {
 const form=document.getElementById('vacation-form'), company=document.getElementById('empresa_id'), employee=document.getElementById('personal_id'), approver=document.getElementById('autorizado_por_personal_id'), start=document.getElementById('fecha_inicio'), end=document.getElementById('fecha_fin'), panel=document.getElementById('preview');
 const refreshPeople=async()=>{ const selected=company.value; employee.innerHTML='<option value="">Selecciona un colaborador</option>'; approver.innerHTML='<option value="">Selecciona quién autorizó</option>'; if(!selected)return; try { const response=await fetch(`{{ route('vacaciones.create') }}?empresa_id=${encodeURIComponent(selected)}`,{headers:{'X-Requested-With':'XMLHttpRequest'}}); const html=await response.text(); const doc=new DOMParser().parseFromString(html,'text/html'); for(const id of ['personal_id','autorizado_por_personal_id']) { const source=doc.getElementById(id); const target=document.getElementById(id); for(const option of [...source.options].slice(1)) target.add(option.cloneNode(true)); } if(window.jQuery&&jQuery.fn.select2){jQuery('#personal_id,#autorizado_por_personal_id').trigger('change.select2');} } catch(e) { panel.textContent='No fue posible cargar el personal de la empresa.'; } update(); };
 const update=async()=>{ if(!company.value||!employee.value||!start.value||!end.value)return; panel.textContent='Calculando…'; try {const response=await fetch('{{ route('vacaciones.preview') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({empresa_id:company.value,personal_id:employee.value,fecha_inicio:start.value,fecha_fin:end.value})}); const data=await response.json(); if(!response.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||'No se pudo calcular el periodo.'); panel.replaceChildren(); const total=document.createElement('strong'); total.textContent=`${data.total} día(s) vacacional(es) a descontar`; panel.append(total); const list=document.createElement('div'); list.className='small mt-2'; for(const day of data.dias){const row=document.createElement('div'); row.className='d-flex justify-content-between border-top py-1'; const date=document.createElement('span'); date.textContent=`${day.fecha}${day.festivos.length?` · ${day.festivos.join(', ')}`:''}`; const state=document.createElement('span'); state.className=day.cuenta?'text-success':'text-muted'; state.textContent=`${day.cuenta?'Cuenta':'No cuenta'} · ${day.motivo}`; row.append(date,state); list.append(row);} panel.append(list); }catch(error){panel.textContent=error.message;} };
 company.addEventListener('change',refreshPeople); [employee,start,end].forEach(el=>el.addEventListener('change',update)); form.addEventListener('submit',e=>{ e.preventDefault(); Swal.fire({icon:'question',title:'¿Registrar vacaciones?',text:'Confirma el periodo y los días vacacionales calculados.',showCancelButton:true,confirmButtonText:'Sí, registrar',cancelButtonText:'Revisar',buttonsStyling:false,reverseButtons:true,customClass:{confirmButton:'btn-hr btn-primary-hr',cancelButton:'btn-hr btn-outline-hr'}}).then(result=>{if(result.isConfirmed)HTMLFormElement.prototype.submit.call(form);}); });
})();
</script>
